#include "zplaytest.h"
#include "zhash.h"
#include "zbuild.h"
#include "zasset_import.h"
#include <SDL3/SDL.h>
#include <fstream>
#include <sstream>
#include <algorithm>
#include <ctime>
#include <map>
#include <mutex>
namespace {
bool word(const std::string &s){return !s.empty()&&s.size()<=160&&s.find_first_of("|\r\n")==std::string::npos;}
std::string fileKey(const std::string &root,const std::string &relative){if(relative.compare(0,9,"original:")==0)return relative;std::string path;if(!ZCampaign_SafeAsset(root,relative,path))return "missing";SDL_PathInfo info;if(!SDL_GetPathInfo(path.c_str(),&info))return "missing";static std::mutex mutex;std::lock_guard<std::mutex> lock(mutex);static std::map<std::string,std::pair<std::string,std::string>> cache;std::string stamp=std::to_string(info.size)+":"+std::to_string(info.modify_time);auto previous=cache.find(path);if(previous!=cache.end()&&previous->second.first==stamp)return previous->second.second;
 std::ifstream in(path,std::ios::binary);std::string blocks;char buffer[524288];size_t total=0;while(in){in.read(buffer,sizeof(buffer));auto count=in.gcount();total+=count;if(total>512*1024*1024)return "oversized";if(count)blocks+=ZSHA256(buffer,count);}auto key=ZSHA256(blocks.data(),blocks.size());if(cache.size()>512)cache.clear();cache[path]={stamp,key};return key;}
bool authored(const ZCampaign &c){std::string marker,relative=c.id+"/.zod-authoring",resolved;return word(c.id)&&ZCampaign_SafeAsset(c.root,".zod-authoring",marker)&&ZCampaign_SafeAsset(ZCampaign_Root(),relative,resolved)&&marker==resolved;}
}
std::string ZPlaytest_Fingerprint(const ZCampaign &c,int index){if(index<0||index>=(int)c.missions.size())return "";const auto &m=c.missions[index];std::ostringstream data;data<<m.uid<<'|'<<m.title<<'|'<<m.briefing<<'|'<<m.speaker<<'|'<<m.character<<'|'<<fileKey(c.root,m.map)<<'|'<<fileKey(c.root,m.video)<<'|'<<fileKey(c.root,m.victoryVideo);auto branch=[&](int next){return next==-1?std::string("default"):next==-2?std::string("end"):next>=0&&next<(int)c.missions.size()?c.missions[next].uid:std::string("invalid");};data<<'|'<<branch(m.nextWin)<<'|'<<branch(m.nextLoss);for(auto &o:m.objectives)data<<'|'<<ZMission_Encode(o);for(auto &e:m.events)data<<'|'<<ZMission_EncodeEvent(e);auto text=data.str();return ZSHA256(text.data(),text.size());}
std::vector<ZPlaytestRecord> ZPlaytest_Read(const ZCampaign &c){std::vector<ZPlaytestRecord> out;if(!authored(c))return out;SDL_PathInfo info;auto path=c.root+"/.playtest-report";if(!SDL_GetPathInfo(path.c_str(),&info)||info.size>524288)return out;std::ifstream in(path);std::string line;while(out.size()<2048&&std::getline(in,line)){std::istringstream row(line);ZPlaytestRecord r;std::string timestamp;std::getline(row,r.uid,'|');std::getline(row,r.fingerprint,'|');std::getline(row,r.event,'|');std::getline(row,r.next,'|');std::getline(row,r.build,'|');std::getline(row,timestamp);if(!word(r.uid)||r.fingerprint.size()!=64||!word(r.event)||!word(r.next)||!word(r.build)||timestamp.empty()||timestamp.size()>18||timestamp.find_first_not_of("0123456789")!=std::string::npos)continue;r.timestamp=strtoll(timestamp.c_str(),nullptr,10);out.push_back(r);}return out;}
bool ZPlaytest_Event(const ZCampaign &snapshot,int index,const std::string &event,int next){const char *source=SDL_getenv("ZOD_EDITOR_TEST_SOURCE");if(!source||index<0||index>=(int)snapshot.missions.size())return false;const std::vector<std::string> allowed={"start","briefing","victory","defeat","intro-video-attempt","victory-video-attempt"};if(std::find(allowed.begin(),allowed.end(),event)==allowed.end())return false;ZCampaign campaign;std::string error;if(!ZCampaign_Load(source,campaign,error)||!authored(campaign))return false;const auto &m=snapshot.missions[index];if(std::none_of(campaign.missions.begin(),campaign.missions.end(),[&](const ZCampaignMission &candidate){return candidate.uid==m.uid;}))return false;auto records=ZPlaytest_Read(campaign);ZPlaytestRecord record;record.uid=m.uid;record.fingerprint=ZPlaytest_Fingerprint(snapshot,index);record.event=event;record.next=next==-2?"end":next>=0&&next<(int)snapshot.missions.size()?snapshot.missions[next].uid:"-";record.build=ZBuild_ID();record.timestamp=std::time(nullptr);records.erase(std::remove_if(records.begin(),records.end(),[&](const ZPlaytestRecord &r){return r.uid==record.uid&&r.fingerprint==record.fingerprint&&r.event==record.event&&r.next==record.next;}),records.end());if(records.size()>=2048)records.erase(records.begin());records.push_back(record);auto path=campaign.root+"/.playtest-report";std::ofstream out(path+".tmp");for(auto &r:records)out<<r.uid<<'|'<<r.fingerprint<<'|'<<r.event<<'|'<<r.next<<'|'<<r.build<<'|'<<r.timestamp<<'\n';out.close();return out&&SDL_RenamePath((path+".tmp").c_str(),path.c_str());}
std::string ZPlaytest_Report(const ZCampaign &c){auto records=ZPlaytest_Read(c);std::ostringstream out;out<<"Campaign playtest coverage: "<<c.title<<"\nBuild: "<<ZBuild_ID()<<"\nCoverage is tied to mission content. Video entries record attempts, not completion.\n";for(size_t i=0;i<c.missions.size();++i){auto key=ZPlaytest_Fingerprint(c,i);out<<i+1<<". "<<c.missions[i].title<<" ["<<c.missions[i].uid<<"]\n";bool found=false;for(auto &r:records)if(r.uid==c.missions[i].uid&&r.fingerprint==key){found=true;out<<"  "<<r.event<<" -> "<<r.next<<" / "<<r.build<<" / UTC epoch "<<r.timestamp<<"\n";}if(!found)out<<"  Not tested for current saved content\n";}return out.str();}
